const $ = s => document.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = v => v == null ? '—' : new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(v);
const num = v => v == null ? '—' : new Intl.NumberFormat('fr-FR',{maximumFractionDigits:2}).format(v);
const date = v => new Date(v).toLocaleDateString('fr-FR');
const labels = {transaction:'Projet',price_eur:'Prix du bien',rent_monthly:'Loyer mensuel affiché (€)',rent_charges_monthly:'Charges locatives / mois',rent_charges_included:'Loyer charges comprises',furnished:'Meublé',area_m2:'Surface habitable',city:'Ville',postal_code:'Code postal',district:'Quartier',address:'Adresse retenue',property_type:'Type de bien',rooms:'Pièces',dpe:'DPE',ges:'GES',dpe_kwh_m2:'Consommation DPE (kWh/m²/an)',ges_kg_m2:'Émissions GES (kg CO₂/m²/an)',floor:'Étage',charges_annual:'Charges / an',tax_annual:'Taxe foncière / an',parking_extra:'Parking en supplément',works_eur:'Travaux',station_minutes:'Gare à pied (min)',delivery:'Année / livraison'};
const numericFacts = new Set(['rent_monthly','rent_charges_monthly','price_eur','area_m2','charges_annual','tax_annual','parking_extra','works_eur','station_minutes','dpe_kwh_m2','ges_kg_m2']);
const PURCHASE_FIELDS=new Set(['price_eur','charges_annual','tax_annual','parking_extra','works_eur','property_type']),RENT_FIELDS=new Set(['rent_monthly','rent_charges_monthly','rent_charges_included','furnished']);
const savedProject=(()=>{try{return localStorage.getItem('repere_project');}catch(_){return null;}})();
const state = {project:savedProject==='Location'?'Location':'Achat',token:localStorage.getItem('repere_token') || '',listings:[],profile:{},scenarios:[],status:{},selected:new Set(),filter:'',type:'',onlyFavorites:false,sort:'recent',mode:'payment',lastSimulation:null,simInputs:null};
let sequence = 0, toastTimer, editing = null, previousRoute = '';

async function api(path, method='GET', body) {
  const r = await fetch('/api'+path,{method,headers:{'X-Repere-Token':state.token,'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});
  const data = await r.json();
  if (!r.ok) {
    if (r.status===401) showLogin();
    let detail=data.detail;
    if(Array.isArray(detail)) detail=detail.map(x=>`${x.loc?.slice(1).join(' · ')} : ${x.msg}`).join('\n');
    throw new Error(typeof detail==='string'?detail:'La demande n’a pas pu être traitée.');
  }
  return data;
}
function toast(message){ $('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4500); }
function showLogin(){ $('#shell').hidden=true;$('#login').hidden=false; }
async function refresh(){ [state.listings,state.profile,state.scenarios,state.status]=await Promise.all([api('/listings'),api('/profile'),api('/scenarios'),api('/status')]);$('#nav-count').textContent=state.listings.length;state.selected=new Set([...state.selected].filter(id=>state.listings.some(x=>x.id===id))); }
async function boot(){if(!state.token){showLogin();return;}try{await refresh();$('#login').hidden=true;$('#shell').hidden=false;await route();}catch(e){showLogin();$('#login-error').textContent=e.message;}}
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();state.token=$('#login-token').value.trim();const button=e.submitter;button.disabled=true;try{await api('/status');localStorage.setItem('repere_token',state.token);await boot();}catch(error){$('#login-error').textContent=error.message;}finally{button.disabled=false;}});

function heading(title,subtitle,over='MON PROJET IMMOBILIER',right=''){return `<div class="page-heading"><div><span class="eyebrow">${over}</span><h1>${title}</h1><p class="muted">${subtitle}</p></div>${right}</div>`;}
function stat(label,value,sub='',accent=false){return `<div class="stat${accent?' accent':''}"><div class="label">${label}</div><div class="value">${value}</div><span class="small">${sub}</span></div>`;}
function empty(title,description,action='import',button='Ajouter une annonce'){return `<div class="empty"><span class="empty-icon">⌂</span><h2>${title}</h2><p>${description}</p><button class="btn primary" data-action="${action}">${button}</button></div>`;}
function field(name,label,value='',{type='number',unit='',min='0',step='any',required=false,placeholder='',span=false}={}){return `<label class="field${span?' span2':''}">${label}${unit?` <small>${unit}</small>`:''}<input name="${esc(name)}" type="${type}" value="${esc(value??'')}" ${type==='number'?`min="${min}" step="${step}"`:''} ${required?'required':''} placeholder="${esc(placeholder)}"></label>`;}
function selectField(name,label,value,options){return `<label class="field">${label}<select name="${esc(name)}">${options.map(x=>{const [v,l]=Array.isArray(x)?x:[x,x];return `<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(l)}</option>`;}).join('')}</select></label>`;}
const HEART='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 21s-7.5-4.6-9.6-9.2C.9 8.4 2.9 4.5 6.6 4.1c2.1-.2 3.9.9 5.4 2.8 1.5-1.9 3.3-3 5.4-2.8 3.7.4 5.7 4.3 4.2 7.7C19.5 16.4 12 21 12 21z"/></svg>';
function photoTag(row,cls='property-photo-img'){return `<img class="${cls}" data-photo="${esc(row.id)}" data-version="${esc(row.photo||'')}" alt="" hidden>`;}
function projectOf(row){return row?.facts?.transaction==='Location'?'Location':'Achat';}
function rentTotal(f){if(f.rent_monthly==null)return null;return f.rent_monthly+(f.rent_charges_included==='Non'&&f.rent_charges_monthly?f.rent_charges_monthly:0);}
function rentDetail(f){if(f.rent_monthly==null)return '';if(f.rent_charges_included==='Oui')return 'charges comprises';if(f.rent_charges_included==='Non')return f.rent_charges_monthly?`+ ${money(f.rent_charges_monthly)} de charges`:'hors charges';return f.rent_charges_monthly?`dont ou + ${money(f.rent_charges_monthly)} de charges`:'';}
function setProject(project){state.project=project==='Location'?'Location':'Achat';try{localStorage.setItem('repere_project',state.project);}catch(_){}state.selected=new Set([...state.selected].filter(id=>projectOf(state.listings.find(x=>x.id===id))===state.project));}
function card(row){const f=row.facts;const rent=projectOf(row)==='Location';const details=[f.area_m2!=null?num(f.area_m2)+' m²':null,f.rooms,rent&&f.furnished&&f.furnished!=='Inconnu'?f.furnished:null,f.city].filter(Boolean).join(' · ')||'Surface, pièces et ville à compléter';const priceLabel=rent?(f.rent_monthly!=null?`${money(f.rent_monthly)}<small class="per-month"> /mois</small>`:'Loyer à compléter'):(f.price_eur!=null?money(f.price_eur):'Prix à compléter');return `<article class="property-card"><button class="property-photo" data-action="edit" data-id="${row.id}" title="${esc(row.title)}" aria-label="Ouvrir la fiche : ${esc(row.title)}">${row.photo?photoTag(row):''}<span class="photo-placeholder" aria-hidden="true">⌂</span></button>${row.favorite?'<span class="fav-badge">Favori</span>':''}<button class="heart${row.favorite?' active':''}" data-action="favorite" data-id="${row.id}" aria-pressed="${row.favorite}" aria-label="${row.favorite?'Retirer des':'Ajouter aux'} favoris">${HEART}</button><div class="property-body"><div class="property-price"><button data-action="edit" data-id="${row.id}">${priceLabel}</button>${rent&&rentDetail(f)?`<span class="rent-detail">${esc(rentDetail(f))}</span>`:''}</div><div class="property-line">${esc(details)}</div><div class="property-bottom"><span class="row"><span class="tag${row.reviewed?'':' warn'}">${row.reviewed?esc(row.status):'À vérifier'}</span>${f.dpe&&f.dpe!=='NC'?`<span class="dpe ${esc(f.dpe)}">DPE ${esc(f.dpe)}</span>`:''}</span><span class="row"><label class="compare-check"><input type="checkbox" data-compare="${row.id}" ${state.selected.has(row.id)?'checked':''}>Comparer</label>${rent?'':`<button class="btn quiet small" data-action="simulate" data-id="${row.id}">Simuler ↗</button>`}</span></div></div></article>`;}
// Photos servies par Repère avec le code de connexion, puis gardées en mémoire (URL blob) le temps de la session.
const photoCache=new Map();
async function loadPhotos(scope=document){if(!scope)return;const images=[...scope.querySelectorAll('img[data-photo]')];let index=0;const next=async()=>{while(index<images.length){const img=images[index++];const key=img.dataset.photo+':'+img.dataset.version;try{if(!photoCache.has(key)){const r=await fetch('/api/listings/'+img.dataset.photo+'/photo',{headers:{'X-Repere-Token':state.token}});if(!r.ok)continue;photoCache.set(key,URL.createObjectURL(await r.blob()));}img.src=photoCache.get(key);img.hidden=false;}catch(_){}}};await Promise.all([next(),next(),next(),next()]);}
function currentListings(){const amount=row=>state.project==='Location'?rentTotal(row.facts):row.facts.price_eur;return state.listings.filter(row=>projectOf(row)===state.project&&(!state.onlyFavorites||row.favorite)&&(state.project==='Location'||!state.type||row.facts.property_type===state.type)&&foldText(row.title+' '+row.facts.city+' '+(row.facts.district||'')).includes(foldText(state.filter))).sort((a,b)=>state.sort==='price'?(amount(a)??Infinity)-(amount(b)??Infinity):state.sort==='area'?(b.facts.area_m2??-1)-(a.facts.area_m2??-1):new Date(b.created_at)-new Date(a.created_at));}
function foldText(s){return String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();}
function selectionBar(){return state.selected.size?`<div class="selection-bar"><span>${state.selected.size} annonce${state.selected.size>1?'s':''} sélectionnée${state.selected.size>1?'s':''}</span><a class="btn" href="#compare">Comparer maintenant →</a></div>`:'';}
function renderCards(){const list=currentListings();const other=state.listings.some(x=>projectOf(x)===state.project);$('#listing-cards').innerHTML=list.length?`<div class="announcement-grid">${list.map(card).join('')}</div>`:empty(state.project==='Location'?'Aucune location ici':'Aucun achat ici',other?'Ajustez les filtres pour retrouver vos annonces.':state.project==='Location'?'Capturez une annonce de location : elle sera rangée ici automatiquement.':'Ajoutez une annonce depuis son URL, du texte ou l’extension.');$('#selection').innerHTML=selectionBar();loadPhotos($('#listing-cards'));}
function dashboard(){const active=state.listings.filter(x=>x.status!=='Écarté');const middle=v=>{v=v.filter(x=>x!=null).sort((a,b)=>a-b);return v.length?(v[Math.floor((v.length-1)/2)]+v[Math.floor(v.length/2)])/2:null;};const buying=active.filter(x=>projectOf(x)==='Achat'),renting=active.filter(x=>projectOf(x)==='Location');const median=middle(buying.map(x=>x.facts.price_eur)),rentMedian=middle(renting.map(x=>rentTotal(x.facts)));const profile=state.profile;const available=profile.savings_eur==null?null:Math.max(0,profile.savings_eur-profile.reserve_eur);const capacity=profile.target_monthly??(profile.income_monthly?Math.max(0,profile.income_monthly*profile.effort_limit_pct/100-profile.existing_debts_monthly):null);return heading('Votre prochain chez-vous.','Gardez le cap sur votre recherche, vos favoris et votre budget.')+(!profile.income_monthly?`<div class="hero-note"><div><strong>Un projet qui part de votre budget.</strong><p>Renseignez vos revenus, votre épargne et vos hypothèses pour personnaliser les simulations.</p></div><a class="btn" href="#profile">Définir mon budget →</a></div>`:'')+`<div class="stats">${stat('Annonces en étude',active.length,`${buying.length} à l’achat · ${renting.length} en location · ${state.listings.filter(x=>!x.reviewed).length} à vérifier`)}${stat('Prix médian',money(median),'annonces à l’achat')}${stat('Loyer médian',rentMedian==null?'—':money(rentMedian)+' /mois','annonces en location, charges connues incluses')}${stat('Apport disponible',money(available),'après réserve souhaitée',true)}</div><div class="dashboard-columns"><section><div class="section-head"><h2>Vos dernières découvertes</h2><a class="btn quiet small" href="#annonces">Tout voir →</a></div>${active.length?`<div class="announcement-grid">${active.slice(0,2).map(card).join('')}</div>`:empty('La recherche commence ici.','Enregistrez une annonce qui vous plaît et retrouvez ici les chiffres pour vous projeter.')}</section><section><div class="section-head"><h2>Votre point de départ</h2></div><div class="budget-card"><span class="eyebrow">MENSUALITÉ CIBLE</span><div class="big">${money(capacity)}</div><span class="small">crédits du projet et assurance</span><div class="budget-track"><i style="width:${capacity!=null&&profile.income_monthly?Math.min(100,capacity/profile.income_monthly*100):0}%"></i></div><span class="small">${capacity!=null&&profile.income_monthly?num(capacity/profile.income_monthly*100)+" % des revenus renseignés":"Revenus à renseigner"}</span><dl><dt>Durée envisagée</dt><dd>${profile.loan_years} ans</dd><dt>Taux nominal retenu</dt><dd>${num(profile.annual_rate_pct)} %</dd><dt>Réserve à conserver</dt><dd>${money(profile.reserve_eur)}</dd></dl><a class="btn full" href="#finance">Explorer une simulation ↗</a><p class="small" style="margin:15px 0 0">Hypothèses modifiables, à confirmer avec votre financement.</p></div></section></div><div class="section-head"><h2>Plusieurs façons d’ajouter une annonce</h2></div><div class="import-methods"><div class="method"><strong>01 · Depuis le navigateur</strong><p>L’extension capture la page que vous consultez, y compris son HTML utile.</p></div><div class="method"><strong>02 · Depuis un lien</strong><p>Collez une URL publique. Si le site bloque l’accès, passez par l’extension.</p></div><div class="method"><strong>03 · À partir d’un contenu</strong><p>Collez du texte, du HTML, ou importez une capture JSON à réanalyser.</p></div></div>`;}
function listingsView(){const count=p=>state.listings.filter(x=>projectOf(x)===p).length;const rent=state.project==='Location';return heading('Les annonces qui comptent.',rent?'Les logements à louer qui vous intéressent, loyer et charges compris.':'Retrouvez les biens qui vous intéressent et vérifiez leurs informations.')+`<div class="project-tabs" role="tablist" aria-label="Projet"><button role="tab" aria-selected="${!rent}" class="${rent?'':'active'}" data-action="project" data-project="Achat">Acheter <b>${count('Achat')}</b></button><button role="tab" aria-selected="${rent}" class="${rent?'active':''}" data-action="project" data-project="Location">Louer <b>${count('Location')}</b></button></div><div class="toolbar"><input id="listing-search" aria-label="Rechercher une annonce" placeholder="Rechercher une ville, un quartier, une annonce…" value="${esc(state.filter)}">${rent?'':`<select id="listing-type" aria-label="Type de bien"><option value="">Tous les types</option>${['Neuf','Ancien','Ancien récent','Inconnu'].map(x=>`<option ${state.type===x?'selected':''}>${x}</option>`).join('')}</select>`}<select id="listing-sort" aria-label="Trier les annonces"><option value="recent">Plus récentes</option><option value="price" ${state.sort==='price'?'selected':''}>${rent?'Loyer croissant':'Prix croissant'}</option><option value="area" ${state.sort==='area'?'selected':''}>Surface décroissante</option></select><button class="btn${state.onlyFavorites?' primary':''}" data-action="filter-favorites">☆ Favoris</button><button class="btn quiet" data-action="manual">Saisie manuelle</button></div><div id="listing-cards"></div><div id="selection"></div>`;}

function defaultSimulation(row){const f=row?.facts||{},p=state.profile;return {price_eur:f.price_eur??'',acquisition_fees_pct:f.property_type==='Neuf'?p.fees_new_pct:p.fees_old_pct,acquisition_fees_eur:null,works_eur:f.works_eur??0,parking_extra:f.parking_extra??0,other_fees_eur:0,down_payment:p.savings_eur==null?0:Math.max(0,p.savings_eur-p.reserve_eur),loan_years:p.loan_years,annual_rate_pct:p.annual_rate_pct,insurance_pct:p.insurance_pct,additional_loans:[],charges_annual:f.charges_annual??null,tax_annual:f.tax_annual??null,maintenance_annual:null,income_monthly:p.income_monthly,existing_debts_monthly:p.existing_debts_monthly,savings_eur:p.savings_eur,reserve_eur:p.reserve_eur,effort_limit_pct:p.effort_limit_pct,mode:state.mode,target_monthly:p.target_monthly??(p.income_monthly?Math.max(1,Math.round(p.income_monthly*p.effort_limit_pct/100-p.existing_debts_monthly)):null)};}
async function compareView(seq){const chosen=state.listings.filter(x=>state.selected.has(x.id));if(!chosen.length){$('#view').innerHTML=heading('Les bons critères, côte à côte.','Sélectionnez jusqu’à quatre annonces pour comparer les biens et leur financement.')+empty('Construisez votre comparaison.','Cochez « Comparer » sur les fiches de votre sélection.','go-listings','Choisir des annonces');return;}
  if(projectOf(chosen[0])==='Location'){rentCompareView(chosen);return;}
  $('#view').innerHTML=heading('Comparer pour mieux choisir.','Les mêmes hypothèses de financement, appliquées à votre sélection.')+`<div class="notice">Taux ${num(state.profile.annual_rate_pct)} %, durée ${state.profile.loan_years} ans, assurance ${num(state.profile.insurance_pct)} %. Les frais sont estimés à ${num(state.profile.fees_old_pct)} % dans l’ancien ou si le type est inconnu, ${num(state.profile.fees_new_pct)} % dans le neuf. <a href="#profile"><u>Modifier les hypothèses</u></a></div><div class="panel table-scroll"><table class="compare-table"><thead><tr><th>VOTRE SÉLECTION</th>${chosen.map(x=>`<td><strong>${esc(x.title)}</strong><p class="small">${esc(x.facts.city||'Ville inconnue')}</p><button class="btn small" data-action="simulate" data-id="${x.id}">Simuler</button> <button class="btn quiet small" data-action="unselect" data-id="${x.id}">Retirer</button></td>`).join('')}</tr></thead><tbody id="compare-body"><tr><td>Calcul en cours…</td></tr></tbody></table></div>`;
  const simulations=await Promise.all(chosen.map(async x=>{if(!x.facts.price_eur)return {error:'Prix manquant'};try{return await api('/simulate','POST',{...defaultSimulation(x),mode:'payment'});}catch(e){return {error:e.message};}}));if(seq!==sequence)return;
  const line=(label,fn)=>`<tr><th>${label}</th>${chosen.map((x,i)=>`<td>${fn(x,simulations[i])}</td>`).join('')}</tr>`;
  $('#compare-body').innerHTML=line('Prix',x=>`<strong class="table-price">${money(x.facts.price_eur)}</strong>`)+line('Surface',x=>num(x.facts.area_m2)+' m²')+line('Prix / m²',x=>x.facts.price_eur&&x.facts.area_m2?money(x.facts.price_eur/x.facts.area_m2):'—')+line('Type',x=>esc(x.facts.property_type))+line('DPE',x=>`<span class="dpe ${esc(x.facts.dpe)}">${esc(x.facts.dpe)}</span>`)+line('Apport retenu',(_,s)=>s.error?'—':money(s.down_payment))+line('Mensualité maximale',(_,s)=>s.error?`<span class="error small">${esc(s.error)}</span>`:`<strong>${money(s.peak_monthly)}</strong><p class="small">assurance comprise</p>`)+line('Budget mensuel connu',(_,s)=>s.error?'—':money(s.known_housing_monthly)+`<p class="small">${s.missing_costs.length?'Partiel : '+esc(s.missing_costs.join(', '))+' à compléter':'Crédits, assurance et coûts renseignés'}</p>`)+line('Charges / an',x=>money(x.facts.charges_annual))+line('Taxe foncière / an',x=>money(x.facts.tax_annual))+line('Gare à pied',x=>num(x.facts.station_minutes)+' min')+line('Suivi',x=>esc(x.status))+line('Notes personnelles',x=>esc(x.notes||'—'));
}

function rentCompareView(chosen){const income=state.profile.income_monthly;const line=(label,fn)=>`<tr><th>${label}</th>${chosen.map(x=>`<td>${fn(x.facts,x)}</td>`).join('')}</tr>`;$('#view').innerHTML=heading('Comparer pour mieux choisir.','Loyers, charges et surfaces de vos locations, côte à côte.')+`<div class="notice">${income?`Part des revenus calculée sur vos revenus mensuels renseignés (${money(income)}). Repère courant : un loyer total sous le tiers des revenus.`:'Renseignez vos revenus dans <a href="#profile"><u>Mon budget</u></a> pour voir la part du loyer dans votre budget.'} Énergie et assurance habitation ne sont pas incluses.</div>`+`<div class="panel table-scroll"><table class="compare-table"><thead><tr><th>VOS LOCATIONS</th>${chosen.map(x=>`<td><strong>${esc(x.title)}</strong><p class="small">${esc(x.facts.city||'Ville inconnue')}</p><button class="btn quiet small" data-action="unselect" data-id="${x.id}">Retirer</button></td>`).join('')}</tr></thead><tbody>`+line('Loyer affiché',f=>`<strong class="table-price">${f.rent_monthly!=null?money(f.rent_monthly)+' /mois':'—'}</strong><p class="small">${esc(rentDetail(f)||'Charges à préciser')}</p>`)+line('Coût mensuel connu',f=>{const t=rentTotal(f);return t==null?'—':`<strong>${money(t)}</strong>${f.rent_charges_included==='Inconnu'&&f.rent_charges_monthly?'<p class="small">Charges peut-être en plus : à vérifier</p>':''}`;})+line('Part des revenus',f=>{const t=rentTotal(f);return t==null||!income?'—':`${num(t/income*100)} %`;})+line('Surface',f=>f.area_m2!=null?num(f.area_m2)+' m²':'—')+line('Loyer / m²',f=>rentTotal(f)!=null&&f.area_m2?money(rentTotal(f)/f.area_m2):'—')+line('Pièces',f=>esc(f.rooms||'—'))+line('Meublé',f=>esc(f.furnished&&f.furnished!=='Inconnu'?f.furnished:'—'))+line('DPE',f=>`<span class="dpe ${esc(f.dpe)}">${esc(f.dpe)}</span>`)+line('Gare à pied',f=>f.station_minutes!=null?num(f.station_minutes)+' min':'—')+line('Suivi',(f,x)=>esc(x.status))+line('Notes personnelles',(f,x)=>esc(x.notes||'—'))+`</tbody></table></div>`;}
function loanBlock(loan={}){return `<div class="loan-block"><div class="row between"><strong>Prêt complémentaire</strong><button type="button" class="btn quiet small" data-action="remove-loan">Retirer</button></div><div class="form-grid">${field('aux-name','Nom du prêt',loan.name||'',{type:'text',required:true,placeholder:'PTZ, Action Logement…'})}${field('aux-amount','Montant',loan.amount,{unit:'€',required:true})}${field('aux-rate','Taux nominal',loan.annual_rate_pct??0,{unit:'% / an',required:true})}${field('aux-months','Durée de remboursement',loan.repayment_months??180,{unit:'mois, après différé',step:1,required:true,min:1})}${field('aux-deferral','Différé de capital',loan.deferral_months??0,{unit:'mois',step:1,required:true})}${field('aux-insurance','Assurance sur capital initial',loan.insurance_pct??0,{unit:'% / an',required:true})}</div></div>`;}
function scenariosHTML(){return `<div class="section-head"><h2>Vos scénarios enregistrés</h2><span class="small">${state.scenarios.length} scénario(s)</span></div><div class="scenario-list">${state.scenarios.length?state.scenarios.map(x=>`<div class="scenario-row"><div><strong>${esc(x.name)}</strong><p class="small">${date(x.created_at)} · apport ${money(x.result.down_payment)} · mensualité maximale ${money(x.result.peak_monthly)}</p></div><div class="row"><button class="btn small" data-action="load-scenario" data-id="${x.id}">Ouvrir</button><button class="btn quiet small" data-action="delete-scenario" data-id="${x.id}" aria-label="Supprimer ${esc(x.name)}">×</button></div></div>`).join(''):'<div class="panel small muted">Enregistrez une simulation pour comparer vos différentes options.</div>'}</div>`;}
function financeView(id){const row=state.listings.find(x=>x.id===id);state.simListingId=row?.id||null;const s=state.simInputs||defaultSimulation(row);state.simInputs=null;state.mode=s.mode||'payment';state.lastSimulation=null;return heading('Donnez des chiffres à votre projet.','Ajustez votre apport ou votre mensualité cible, puis comparez les scénarios.')+`<div class="finance-layout"><form id="finance-form" class="panel"><div class="segmented"><button type="button" data-action="mode" data-mode="payment" class="${state.mode==='payment'?'active':''}">Apport → mensualités</button><button type="button" data-action="mode" data-mode="contribution" class="${state.mode==='contribution'?'active':''}">Mensualité → apport</button></div>${selectField('listing_id','Bien à simuler',row?.id||'',[['','Saisie libre'],...state.listings.filter(x=>projectOf(x)==='Achat').map(x=>[x.id,x.title])])}<div class="form-section" style="margin-top:24px"><h3>01 · Le coût du projet</h3><div class="form-grid">${field('price_eur','Prix d’achat',s.price_eur,{unit:'€',required:true,min:1})}${field('acquisition_fees_pct','Frais d’acquisition estimés',s.acquisition_fees_pct,{unit:'% du prix',required:true})}${field('acquisition_fees_eur','Ou montant exact des frais',s.acquisition_fees_eur,{unit:'€ · prioritaire sur le pourcentage',placeholder:'Facultatif'})}${field('works_eur','Travaux prévus',s.works_eur,{unit:'€',required:true})}${field('parking_extra','Parking payé séparément',s.parking_extra,{unit:'€ · hors prix du bien',required:true})}${field('other_fees_eur','Garantie et autres frais',s.other_fees_eur,{unit:'€',required:true})}</div></div><div class="form-section"><h3>02 · Le financement</h3><div class="form-grid"><div id="down-payment-field" ${state.mode==='contribution'?'hidden':''}>${field('down_payment','Apport mobilisé',s.down_payment,{unit:'€',required:true})}</div><div id="target-field" ${state.mode==='payment'?'hidden':''}>${field('target_monthly','Mensualité maximale',s.target_monthly,{unit:'€ · crédits du projet + assurance'})}</div>${field('loan_years','Durée du prêt principal',s.loan_years,{unit:'années',step:1,required:true,min:1})}${field('annual_rate_pct','Taux nominal',s.annual_rate_pct,{unit:'% / an',required:true})}${field('insurance_pct','Assurance sur capital initial',s.insurance_pct,{unit:'% / an',required:true})}</div><div class="notice">Les valeurs de départ sont des hypothèses, pas des taux de marché. Renseignez les conditions de votre financement.</div><details ${s.additional_loans?.length?'open':''}><summary>Ajouter un PTZ ou un autre prêt</summary><p class="small">Saisissez les montants et durées confirmés. L’éligibilité n’est pas déduite de l’annonce. Pendant un différé, le capital est différé : les intérêts et l’assurance restent payés.</p><div id="extra-loans">${(s.additional_loans||[]).map(loanBlock).join('')}</div><button type="button" class="btn small" data-action="add-loan">+ Ajouter un prêt</button></details></div><div class="form-section"><h3>03 · Les coûts au quotidien</h3><div class="form-grid">${field('charges_annual','Charges de copropriété',s.charges_annual,{unit:'€ / an',placeholder:'Inconnues'})}${field('tax_annual','Taxe foncière',s.tax_annual,{unit:'€ / an',placeholder:'Inconnue'})}${field('maintenance_annual','Entretien à prévoir',s.maintenance_annual,{unit:'€ / an',placeholder:'Non estimé'})}</div><p class="small" style="margin-top:12px">Un champ vide reste inconnu. Les dépenses d’énergie et de vie ne sont pas incluses.</p></div><details class="form-section"><summary>Revenus et épargne retenus</summary><div class="form-grid" style="margin-top:15px">${field('income_monthly','Revenus nets avant impôt',s.income_monthly,{unit:'€ / mois'})}${field('existing_debts_monthly','Autres crédits',s.existing_debts_monthly,{unit:'€ / mois',required:true})}${field('savings_eur','Épargne disponible',s.savings_eur,{unit:'€'})}${field('reserve_eur','Réserve souhaitée',s.reserve_eur,{unit:'€',required:true})}${field('effort_limit_pct','Seuil d’effort retenu',s.effort_limit_pct,{unit:'%',required:true,min:1})}</div></details><p id="finance-error" class="error small" role="alert"></p><button class="btn primary full" type="submit">Calculer ma simulation ↗</button></form><div id="finance-results" class="finance-results"><div class="panel empty"><span class="empty-icon">↗</span><h2>Chaque hypothèse compte.</h2><p>Complétez les montants à gauche pour voir l’apport, les mensualités et leur évolution.</p></div></div></div><div id="scenarios-section">${scenariosHTML()}</div>`;}
function collectSimulation(){const form=$('#finance-form');const value=name=>{const v=form.elements.namedItem(name)?.value;return v===''||v==null?null:Number(v);};const nullable=new Set(['acquisition_fees_eur','charges_annual','tax_annual','maintenance_annual','income_monthly','savings_eur','target_monthly']);const keys=['price_eur','acquisition_fees_pct','acquisition_fees_eur','works_eur','parking_extra','other_fees_eur','down_payment','loan_years','annual_rate_pct','insurance_pct','charges_annual','tax_annual','maintenance_annual','income_monthly','existing_debts_monthly','savings_eur','reserve_eur','effort_limit_pct','target_monthly'];const s=Object.fromEntries(keys.map(k=>[k,value(k)??(nullable.has(k)?null:0)]));s.mode=state.mode;s.additional_loans=[...document.querySelectorAll('.loan-block')].map(el=>({name:el.querySelector('[name=aux-name]').value,amount:Number(el.querySelector('[name=aux-amount]').value),annual_rate_pct:Number(el.querySelector('[name=aux-rate]').value),repayment_months:Number(el.querySelector('[name=aux-months]').value),deferral_months:Number(el.querySelector('[name=aux-deferral]').value),insurance_pct:Number(el.querySelector('[name=aux-insurance]').value)}));return s;}
function chart(rows,key='payment'){if(!rows.length)return '<p class="small">Aucun emprunt à rembourser.</p>';const w=480,h=180,left=55,right=16,top=16,bottom=32;const max=Math.max(...rows.map(r=>r[key]),1)*1.12;const X=m=>left+(m-1)/Math.max(1,rows.length-1)*(w-left-right),Y=v=>h-bottom-v/max*(h-top-bottom);const points=rows.map(r=>`${X(r.month).toFixed(1)},${Y(r[key]).toFixed(1)}`).join(' ');return `<svg class="chart" role="img" aria-label="${key==='payment'?'Mensualités assurance comprise':'Capital restant dû'} sur la durée du prêt" viewBox="0 0 ${w} ${h}">${[0,.5,1].map(k=>`<line class="grid" x1="${left}" x2="${w-right}" y1="${Y(max*k)}" y2="${Y(max*k)}"/><text x="${left-8}" y="${Y(max*k)+4}" text-anchor="end">${Math.round(max*k).toLocaleString('fr-FR')} €</text>`).join('')}<polyline class="plot" points="${points}"/>${[1,Math.ceil(rows.length/2),rows.length].map(m=>`<text x="${X(m)}" y="${h-8}" text-anchor="middle">${m===1?'Départ':num(m/12)+' ans'}</text>`).join('')}</svg>`;}
function showSimulation(result,inputs){state.lastSimulation={result,inputs};const reverse=inputs.mode==='contribution';$('#finance-results').innerHTML=`<div class="stats">${stat(reverse?'Apport nécessaire':'Mensualité maximale',reverse?money(result.down_payment):money(result.peak_monthly),reverse?'pour respecter la cible':'crédits + assurance',true)}${stat(reverse?'Mensualité maximale':'Apport mobilisé',reverse?money(result.peak_monthly):money(result.down_payment),reverse?'sur toutes les périodes':'hors réserve souhaitée')}${stat('Coût total du projet',money(result.project_cost),'avant intérêts et assurance')}${stat('Budget mensuel connu',money(result.known_housing_monthly),result.missing_costs.length?'Partiel · des coûts manquent':'avec les coûts renseignés')}</div><div class="panel"><div class="row between"><h3>Vos mensualités dans le temps</h3><span class="tag">${inputs.loan_years} ans</span></div>${chart(result.schedule)}<table><thead><tr><th>Période</th><th>Crédits + assurance</th></tr></thead><tbody>${result.phases.map(p=>`<tr><td>Mois ${p.start_month} à ${p.end_month}</td><td><strong>${money(p.monthly)}</strong></td></tr>`).join('')||'<tr><td>Aucun crédit</td><td>0 €</td></tr>'}</tbody></table></div><div class="panel"><h3>Les chiffres à garder en tête</h3><table><tbody>${[['Prêt principal',money(result.main_principal)],['Prêts complémentaires',money(result.additional_principal)],['Total des intérêts',money(result.total_interest)],['Total de l’assurance',money(result.total_insurance)],['Taux d’effort maximal',result.effort_pct==null?'Revenus à renseigner':num(result.effort_pct)+' %'],['Épargne après apport',money(result.cash_remaining)],['Épargne manquante, réserve comprise',money(result.cash_shortfall)],['Solde mensuel après coûts connus',money(result.monthly_remaining_known)]].map(([k,v])=>`<tr><td>${k}</td><td><strong>${v}</strong></td></tr>`).join('')}</tbody></table><p class="small">Le solde mensuel n’intègre pas les dépenses de vie ni les coûts immobiliers restés inconnus.</p><details><summary>Capital restant dû</summary>${chart(result.schedule,'balance')}</details><div class="row wrap" style="margin-top:20px"><button class="btn primary" data-action="save-scenario">Enregistrer ce scénario</button><button class="btn" data-action="export-schedule">Échéancier CSV</button></div></div><div class="notice">${result.warnings.map(w=>`<p style="margin:5px 0">${esc(w)}</p>`).join('')}</div>`;}

function profileView(){const p=state.profile;return heading('Un budget à votre mesure.','Ces informations servent de point de départ aux simulations. Vous pouvez les ajuster pour chaque bien.')+`<form id="profile-form" class="panel profile-form"><div class="form-section"><h3>Votre capacité de financement</h3><div class="form-grid">${field('income_monthly','Revenus nets avant impôt',p.income_monthly,{unit:'€ / mois',placeholder:'À renseigner'})}${field('existing_debts_monthly','Autres crédits en cours',p.existing_debts_monthly,{unit:'€ / mois',required:true})}${field('savings_eur','Épargne disponible',p.savings_eur,{unit:'€',placeholder:'À renseigner'})}${field('reserve_eur','Épargne à conserver',p.reserve_eur,{unit:'€',required:true})}${field('target_monthly','Mensualité cible personnelle',p.target_monthly,{unit:'€ · crédits du projet + assurance',placeholder:'Facultatif'})}${field('effort_limit_pct','Seuil d’effort à comparer',p.effort_limit_pct,{unit:'%',required:true,min:1})}</div></div><div class="form-section"><h3>Vos hypothèses de prêt</h3><div class="form-grid">${field('loan_years','Durée',p.loan_years,{unit:'années',step:1,min:1,required:true})}${field('annual_rate_pct','Taux nominal',p.annual_rate_pct,{unit:'% / an',required:true})}${field('insurance_pct','Assurance sur capital initial',p.insurance_pct,{unit:'% / an',required:true})}</div></div><h3>Frais d’acquisition estimés</h3><div class="form-grid">${field('fees_old_pct','Ancien ou type inconnu',p.fees_old_pct,{unit:'% du prix',required:true})}${field('fees_new_pct','Neuf',p.fees_new_pct,{unit:'% du prix',required:true})}</div><div class="notice">Les taux et frais préremplis sont des exemples modifiables. Le seuil d’effort est un repère, sans validation de financement ni calcul automatique d’éligibilité au PTZ. <a href="https://www.economie.gouv.fr/hcsf/mesures/mesure-relative-loctroi-de-credits-immobiliers" target="_blank" rel="noopener noreferrer"><u>Référence HCSF</u></a>.</div><p id="profile-error" class="error small"></p><button class="btn primary" type="submit">Enregistrer mon budget</button></form>`;}
function settingsView(){return heading('Votre espace, vos données.','Gérez les imports et conservez une copie de votre projet.')+`<div class="settings-grid"><section class="panel"><h3>Importer depuis votre navigateur</h3><p class="muted">Chargez le dossier <strong>extension</strong> du projet dans Chrome ou Edge, puis connectez-le avec le même code que cette application.</p><p class="small">Ouvrez une annonce, lisez le contenu capturé et cliquez sur Ajouter à Repère. Les champs apparaîtront dans une fiche à vérifier.</p><button class="btn" data-action="copy-token">Copier le code pour l’extension</button></section><section class="panel"><h3>Sauvegarde et restauration</h3><p class="muted">La sauvegarde contient les annonces, les captures, votre budget et les scénarios. Les codes de connexion et clés API sont exclus.</p><div class="row wrap"><button class="btn primary" data-action="backup">Télécharger une sauvegarde</button><button class="btn" data-action="restore">Restaurer un fichier</button></div><input type="file" id="restore-file" accept=".json" hidden><p class="small" style="margin-top:12px">La restauration ajoute les éléments absents. Les fiches déjà présentes et le budget déjà enregistré sont conservés.</p></section><section class="panel"><h3>Des méthodes d’extraction complémentaires</h3><p class="small">Métadonnées JSON-LD et microdonnées avec extruct, HTML avec BeautifulSoup, texte principal avec Trafilatura, règles de texte et Gemini facultatif.</p><p class="small">Les sélecteurs spécifiques à un site se configurent dans <strong>config/parsers.json</strong>. Les diagnostics sont accessibles dans chaque fiche.</p><button class="btn" data-action="import">Tester un contenu HTML</button></section><section class="panel"><h3>Complément Gemini</h3><span class="tag${state.status.gemini_configured?' good':' warn'}">${state.status.gemini_configured?'Clé configurée':'Non configuré · facultatif'}</span><p class="small" style="margin-top:15px">Modèle : ${esc(state.status.model)}. La capture est transmise à Gemini uniquement quand vous activez l’option. Les données du profil financier ne sont pas envoyées.</p><p class="small">Configurez GEMINI_API_KEY dans le fichier .env puis recréez le conteneur application.</p></section></div><div class="row between" style="margin-top:30px"><span class="small">Repère ${esc(state.status.version)}${state.status.commit?` · commit ${esc(state.status.commit.slice(0,7))}`:''} · ${esc(state.status.database)}</span><button class="btn quiet" data-action="logout">Déconnecter ce navigateur</button></div>`;}

async function route(){if($('#shell').hidden)return;const seq=++sequence;const [page,id]=(location.hash.slice(1)||'dashboard').split('/');const routeKey=page+'/'+(id||'');if(routeKey!==previousRoute){window.scrollTo(0,0);previousRoute=routeKey;}const active=page==='annonce'?'annonces':page;const names={dashboard:'Vue d’ensemble',annonces:'Mes annonces',compare:'Comparer',finance:'Simuler',profile:'Mon budget',settings:'Paramètres'};document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===active));$('#breadcrumb').textContent=names[active]||'Vue d’ensemble';if(page==='compare'){await compareView(seq);return;}$('#view').innerHTML=page==='annonces'||page==='annonce'?listingsView():page==='finance'?financeView(id):page==='profile'?profileView():page==='settings'?settingsView():dashboard();if(page==='annonces'||page==='annonce')renderCards();else loadPhotos($('#view'));if(page==='annonce'&&id)await openEditor(id);}
window.addEventListener('hashchange',()=>route().catch(e=>toast(e.message)));

function openModal(html){$('#modal-content').innerHTML=html;loadPhotos($('#modal-content'));if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){if($('#modal').open)$('#modal').close();editing=null;}
function modalHead(title,subtitle=''){return `<div class="modal-header"><div><h2>${title}</h2>${subtitle?`<p class="small" style="margin:0">${subtitle}</p>`:''}</div><button class="icon-btn" type="button" data-action="close" aria-label="Fermer">×</button></div>`;}
function openImport(){openModal(`${modalHead('Une nouvelle piste.','Importez une annonce et vérifiez les champs reconnus.')}<form id="import-form"><div class="modal-body"><div class="segmented"><button type="button" class="active" data-action="import-mode" data-mode="url">Lien public</button><button type="button" data-action="import-mode" data-mode="content">Texte / HTML / fichier</button></div><input type="hidden" name="import_mode" value="url">${field('source_url','URL de l’annonce','',{type:'url',placeholder:'https://…'})}<div id="import-content" hidden style="margin-top:18px"><label class="field">Texte ou HTML de l’annonce<textarea name="content" rows="7" placeholder="Collez le contenu de l’annonce, son HTML ou une capture JSON."></textarea></label><label class="field" style="margin-top:14px">Ou choisir un fichier<input id="import-file" type="file" accept=".html,.htm,.txt,.json"></label></div><details class="help"><summary>Méthodes d’extraction</summary><div class="parser-options">${[['structured','Métadonnées'],['html','HTML'],['text','Texte visible'],['trafilatura','Trafilatura']].map(([v,l])=>`<label class="check-line"><input type="checkbox" name="parsers" value="${v}" checked>${l}</label>`).join('')}</div><p>Toutes les méthodes sont locales. Les valeurs contradictoires restent à vérifier.</p></details><label class="check-line" style="margin-top:22px"><input name="use_gemini" type="checkbox">Compléter avec Gemini — transmet le contenu de l’annonce à l’API</label><div class="notice">Pour une page réservée à votre session ou protégée par une vérification, utilisez l’extension dans votre navigateur.</div><p id="import-error" class="error small" role="alert"></p></div><div class="modal-footer"><button type="button" class="btn" data-action="close">Annuler</button><button type="submit" class="btn primary">Analyser et créer la fiche →</button></div></form>`);}

function factFields(f){return Object.entries(labels).map(([key,label])=>[key,key==='transaction'?selectField(key,label,f[key]||'Achat',[['Achat','Achat'],['Location','Location']]):key==='rent_charges_included'?selectField(key,label,f[key]||'Inconnu',['Inconnu','Oui','Non']):key==='furnished'?selectField(key,label,f[key]||'Inconnu',['Inconnu','Meublé','Non meublé']):key==='property_type'?selectField(key,label,f[key],['Inconnu','Neuf','Ancien','Ancien récent']):key==='dpe'||key==='ges'?selectField(key,label,f[key],['NC','A','B','C','D','E','F','G']):field(key,label,f[key],{type:numericFacts.has(key)?'number':'text',placeholder:'Non renseigné'})]).map(([key,html])=>PURCHASE_FIELDS.has(key)?`<div class="only-achat">${html}</div>`:RENT_FIELDS.has(key)?`<div class="only-location">${html}</div>`:html).join('');}
function addressResultsHTML(result){state.addressGroups=result.groups||[];const confidence={forte:['good','Confiance forte'],moyenne:['','Confiance moyenne'],faible:['warn','Confiance faible'],aucune:['warn','Aucune correspondance']}[result.confidence||'aucune']||['','' ];const warn=(result.warnings||[]).map(w=>`<p class="small">${esc(w)}</p>`).join('');const origin=result.automatic?`Recherche automatique après la capture${result.searched_at?' · '+date(result.searched_at):''}`:'Recherche lancée depuis la fiche';if(!state.addressGroups.length)return `<p class="small" style="margin-top:12px">${esc(origin)}</p>${warn}`;
const member=m=>`<li>${esc([m.complement,m.floor!=null&&m.floor!==''?'étage '+m.floor:'',m.area_m2!=null?num(m.area_m2)+' m²':'','DPE '+(m.dpe||'?')+' · GES '+(m.ges||'?'),m.dpe_kwh_m2!=null?num(m.dpe_kwh_m2)+' kWh/m²/an':'',m.date?'DPE du '+date(m.date):''].filter(Boolean).join(' · '))}${m.differences.length?`<br><span class="inline-alert">Écarts : ${esc(m.differences.join(' · '))}</span>`:''}</li>`;
return `<div class="address-summary"><span class="tag ${confidence[0]}">${confidence[1]}</span><span class="small">${esc(origin)} · ${esc(result.criteria||'')}</span></div>${warn}<div class="address-groups">${state.addressGroups.map((g,i)=>`<div class="address-group${i===0?' best':''}"><div class="row between wrap"><div><strong>${esc(g.address)}</strong> <span class="small">${esc([g.postal_code,g.city].filter(Boolean).join(' '))}</span><p class="small" style="margin:3px 0 0">${g.count} logement${g.count>1?'s':''} correspondant${g.count>1?'s':''}${g.distance_km!=null?` · à ${g.distance_km<1?Math.round(g.distance_km*1000)+' m':num(g.distance_km)+' km'} du point de l’annonce`:''}${g.building_year?` · construit en ${g.building_year}`:''}</p></div><div class="row"><button type="button" class="btn small" data-action="use-address" data-index="${i}">Retenir cette adresse</button><a class="btn quiet small" href="${esc(g.map_url)}" target="_blank" rel="noopener noreferrer">Carte ↗</a></div></div><details class="members"><summary>Voir ${g.count>1?'les logements':'le logement'}</summary><ul>${g.members.map(member).join('')}</ul></details></div>`).join('')}</div>`;}
function reportHTML(row){const report=row.report||{};return `<div class="notice">${(report.steps||[]).map(s=>`${esc(s.name)} : ${s.error?'indisponible':s.candidates+' candidat(s)'}`).join(' · ')||'Fiche saisie manuellement.'}</div>${(report.warnings||[]).map(w=>`<p class="small">${esc(w)}</p>`).join('')}<div class="source-list">${Object.entries(report.candidates||{}).map(([field,items])=>`<div class="source-item${report.conflicts?.[field]?' conflict':''}"><strong>${esc(labels[field]||field)} ${report.conflicts?.[field]?'· valeurs contradictoires':''}</strong>${items.map((item,index)=>`<div style="margin-top:8px"><span class="tag">${esc(item.parser)}</span> <strong>${esc(item.value)}</strong> <button type="button" class="btn quiet small" data-action="choose-value" data-field="${esc(field)}" data-index="${index}">Utiliser</button><blockquote>${esc(item.quote)}</blockquote></div>`).join('')}</div>`).join('')}</div>`;}
async function openEditor(id){const row=id?await api('/listings/'+id):{id:null,title:'',facts:{transaction:state.project,property_type:'Inconnu',dpe:'NC'},overrides:{},notes:'',status:'À étudier',report:{},reviewed:false};editing=row;openModal(`${modalHead(id?'Votre fiche d’annonce.':'Une annonce, à votre façon.',id?'Vérifiez les données avant de vous projeter.':'Renseignez les informations dont vous disposez.')}<form id="edit-form" data-transaction="${esc(projectOf(row))}"><div class="modal-body">${id?`<div class="editor-photo">${row.photo?photoTag(row,'editor-photo-img'):'<span class="photo-placeholder" aria-hidden="true">⌂</span>'}<button type="button" class="btn small" data-action="photo-refresh">${row.photo?'Changer la photo':'Récupérer la photo'}</button></div>`:''}${row.url?`<p class="source-url"><a href="${esc(row.url)}" target="_blank" rel="noopener noreferrer">Ouvrir l’annonce d’origine ↗</a></p>`:''}${field('title','Titre de l’annonce',row.title,{type:'text',required:true,span:true})}<div class="form-grid" style="margin-top:20px">${factFields(row.facts)}</div><div class="notice">Les champs que vous corrigez sont conservés lors des prochains imports. Les valeurs absentes restent vides.</div>${selectField('status','Statut de suivi',row.status,['À étudier','À visiter','Visité','Offre','Écarté'])}<label class="field" style="margin-top:16px">Notes personnelles<textarea name="notes" rows="3">${esc(row.notes)}</textarea></label><details class="help" id="address-panel" ${row.report?.address_search?.groups?.length&&!row.facts.address?'open':''}><summary>${row.report?.address_search?.groups?.length?`Adresse probable : ${esc(row.report.address_search.groups[0].address)}`:'Retrouver l’adresse (base DPE publique de l’ADEME)'}</summary><p class="small">Utilise le code postal, la consommation en kWh/m²/an ou, à défaut, la surface et les lettres DPE/GES saisies ci-dessus, puis classe les logements par étage, année de construction et distance au point de l’annonce. Sont envoyés à l’ADEME : le lieu, les valeurs ou lettres du DPE et la surface.</p><button type="button" class="btn small" data-action="find-address">${row.report?.address_search?'Relancer la recherche':'Chercher les adresses possibles'}</button><div id="address-results">${row.report?.address_search?addressResultsHTML(row.report.address_search):''}</div></details><details class="help"><summary>Voir les sources et les diagnostics</summary>${reportHTML(row)}</details>${Object.keys(row.overrides||{}).filter(k=>k!=='title').length?`<details class="help"><summary>Champs corrigés manuellement</summary><p>Vous pouvez rendre un champ à l’extraction automatique :</p>${Object.keys(row.overrides).filter(k=>k!=='title').map(k=>`<button type="button" class="btn small" data-action="unlock" data-field="${esc(k)}">${esc(labels[k]||k)} · réinitialiser</button>`).join(' ')}</details>`:''}${id?`<div class="row wrap" style="margin-top:20px"><button class="btn small" type="button" data-action="reanalyze">Réanalyser la capture</button><button class="btn small" type="button" data-action="reanalyze-gemini">Compléter avec Gemini</button><button class="btn quiet small" type="button" data-action="export-source">Exporter la capture</button></div>`:''}<p id="edit-error" class="error small" role="alert"></p></div><div class="modal-footer"><button type="button" class="btn${id?' danger':''}" data-action="${id?'delete-listing':'close'}">${id?'Supprimer':'Annuler'}</button><div class="row"><button class="btn" type="submit" name="review" value="no">Enregistrer</button><button class="btn primary" type="submit" name="review" value="yes">Valider la fiche ✓</button></div></div></form>`);}

function download(name,content,type='application/json'){const blob=new Blob([typeof content==='string'?content:JSON.stringify(content,null,2)],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function invalidateSimulation(){if(state.lastSimulation&&$('#finance-results')){state.lastSimulation=null;$('#finance-results').innerHTML='<div class="panel muted">Les hypothèses ont changé. Recalculez pour actualiser les résultats.</div>';}}
document.addEventListener('input',e=>{if(e.target.closest('#finance-form'))invalidateSimulation();if(e.target.id==='listing-search'){state.filter=e.target.value;renderCards();}});
document.addEventListener('change',async e=>{try{const el=e.target;if(el.name==='transaction'&&el.form?.id==='edit-form'){el.form.dataset.transaction=el.value;return;}if(el.dataset.compare){if(el.checked&&state.selected.size>=4){el.checked=false;return toast('Sélectionnez jusqu’à quatre annonces.');}const chosenProject=projectOf(state.listings.find(x=>x.id===el.dataset.compare));if(el.checked&&[...state.selected].some(id=>projectOf(state.listings.find(x=>x.id===id))!==chosenProject)){el.checked=false;return toast('Comparez des annonces du même projet : achat ou location.');}el.checked?state.selected.add(el.dataset.compare):state.selected.delete(el.dataset.compare);if($('#selection'))$('#selection').innerHTML=selectionBar();}
if(el.id==='listing-type'){state.type=el.value;renderCards();}if(el.id==='listing-sort'){state.sort=el.value;renderCards();}
if(el.name==='listing_id'){state.simInputs=null;location.hash='finance/'+el.value;if(!el.value)await route();}
if(el.id==='import-file'&&el.files[0]){if(el.files[0].size>2_000_000)throw new Error('Choisissez un fichier de moins de 2 Mo.');$('#import-form [name=content]').value=await el.files[0].text();}
if(el.id==='restore-file'&&el.files[0]){const data=JSON.parse(await el.files[0].text());const result=await api('/restore','POST',data);await refresh();await route();toast(`${result.added} annonce(s) ajoutée(s), ${result.skipped} déjà présente(s).`);}
}catch(error){toast(error.message);}});

document.addEventListener('click',async e=>{const button=e.target.closest('[data-action]');if(!button)return;const action=button.dataset.action,id=button.dataset.id;try{
if(action==='close')closeModal();
else if(action==='import')openImport();
else if(action==='manual')await openEditor(null);
else if(action==='edit')await openEditor(id);
else if(action==='go-listings')location.hash='annonces';
else if(action==='refresh'){button.disabled=true;await refresh();await route();toast('Annonces actualisées.');}
else if(action==='favorite'){const row=state.listings.find(x=>x.id===id);await api('/listings/'+id,'PATCH',{revision:row.revision,favorite:!row.favorite});await refresh();await route();}
else if(action==='project'){setProject(button.dataset.project);await route();}
else if(action==='filter-favorites'){state.onlyFavorites=!state.onlyFavorites;await route();}
else if(action==='unselect'){state.selected.delete(id);await route();}
else if(action==='simulate'){state.simInputs=null;location.hash='finance/'+id;}
else if(action==='mode'){state.mode=button.dataset.mode;document.querySelectorAll('[data-action=mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===state.mode));$('#down-payment-field').hidden=state.mode==='contribution';$('#target-field').hidden=state.mode==='payment';state.lastSimulation=null;$('#finance-results').innerHTML='<div class="panel muted">Recalculez pour appliquer ce mode.</div>';}
else if(action==='add-loan'){if(document.querySelectorAll('.loan-block').length>=5)return toast('Cinq prêts complémentaires au maximum.');$('#extra-loans').insertAdjacentHTML('beforeend',loanBlock());invalidateSimulation();}
else if(action==='remove-loan'){button.closest('.loan-block').remove();invalidateSimulation();}
else if(action==='save-scenario'){if(!state.lastSimulation)return;const name=prompt('Nom de ce scénario :','Mon financement');if(!name?.trim())return;await api('/scenarios','POST',{name:name.trim(),listing_id:state.simListingId,inputs:state.lastSimulation.inputs});state.scenarios=await api('/scenarios');$('#scenarios-section').innerHTML=scenariosHTML();toast('Scénario enregistré.');}
else if(action==='load-scenario'){const s=state.scenarios.find(x=>x.id===id);state.simInputs=s.inputs;history.replaceState(null,'','#finance/'+(s.listing_id||''));await route();showSimulation(s.result,s.inputs);}
else if(action==='delete-scenario'){if(!confirm('Supprimer ce scénario ?'))return;await api('/scenarios/'+id,'DELETE');state.scenarios=await api('/scenarios');$('#scenarios-section').innerHTML=scenariosHTML();}
else if(action==='export-schedule'){const rows=state.lastSimulation?.result.schedule||[];download('echeancier_repere.csv','\uFEFFMois;Capital remboursé;Intérêts;Assurance;Mensualité;Capital restant dû\n'+rows.map(r=>[r.month,r.principal,r.interest,r.insurance,r.payment,r.balance].map(v=>String(v).replace('.',',')).join(';')).join('\n'),'text/csv;charset=utf-8');}
else if(action==='copy-token'){await navigator.clipboard.writeText(state.token);toast('Code copié.');}
else if(action==='backup'){button.disabled=true;download('repere_sauvegarde_'+new Date().toISOString().slice(0,10)+'.json',await api('/backup'));toast('Sauvegarde téléchargée.');}
else if(action==='restore')$('#restore-file').click();
else if(action==='logout'){state.token='';localStorage.removeItem('repere_token');closeModal();showLogin();}
else if(action==='import-mode'){const mode=button.dataset.mode;$('#import-form [name=import_mode]').value=mode;$('#import-content').hidden=mode==='url';document.querySelectorAll('[data-action=import-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));}
else if(action==='choose-value'){const candidate=editing.report.candidates[button.dataset.field][Number(button.dataset.index)];const input=$('#edit-form').elements.namedItem(button.dataset.field);if(input)input.value=candidate.value;toast('Valeur choisie. Enregistrez pour la conserver.');}
else if(action==='unlock'){if(!confirm('Revenir à la valeur extraite pour ce champ ? Les autres modifications non enregistrées seront perdues.'))return;await api('/listings/'+editing.id,'PATCH',{revision:editing.revision,unlock_fields:[button.dataset.field]});await refresh();await openEditor(editing.id);}
else if(action==='reanalyze'||action==='reanalyze-gemini'){if(!confirm('Réanalyser la capture enregistrée ? Les modifications non enregistrées seront perdues.'+(action==='reanalyze-gemini'?' Le contenu de l’annonce sera transmis à Gemini.':'')))return;button.disabled=true;button.textContent='Analyse en cours…';const row=await api('/listings/'+editing.id+'/reanalyze','POST',{use_gemini:action==='reanalyze-gemini'});await refresh();await openEditor(row.id);toast('Analyse terminée. Vérifiez les champs.');}
else if(action==='photo-refresh'){const url=prompt('Adresse d’une image de l’annonce (clic droit sur la photo → « Copier l’adresse de l’image »).\nLaisse vide pour la rechercher automatiquement.','');if(url===null)return;button.textContent='Téléchargement…';await api('/listings/'+editing.id+'/photo','POST',{url:url.trim()||null});await refresh();await openEditor(editing.id);if($('#listing-cards'))renderCards();toast('Photo enregistrée.');}
else if(action==='find-address'){const data=new FormData($('#edit-form'));const n=k=>{const v=String(data.get(k)??'').replace(',','.').trim();return v===''?null:Number(v);};const title=String(data.get('title')||'').toLowerCase();const year=String(data.get('delivery')||'').match(/^\s*(\d{4})\s*$/);const payload={listing_id:editing.id||null,building_year:year&&+year[1]>=1700&&+year[1]<=2100?+year[1]:null,postal_code:String(data.get('postal_code')||'').trim()||null,city:String(data.get('city')||'').trim()||null,dpe_kwh_m2:n('dpe_kwh_m2'),ges_kg_m2:n('ges_kg_m2'),area_m2:n('area_m2'),dpe:data.get('dpe')||'NC',ges:data.get('ges')||'NC',floor:String(data.get('floor')||'').trim()||null,kind:/maison|villa/.test(title)?'maison':/appartement|studio|duplex|loft/.test(title)?'appartement':''};if(!payload.dpe_kwh_m2&&!(payload.area_m2&&(payload.dpe!=='NC'||payload.ges!=='NC')))throw new Error('Renseigne la consommation du DPE (kWh/m²/an), ou la surface avec la lettre DPE.');if(!payload.postal_code&&!payload.city)throw new Error('Renseigne le code postal ou la ville du bien.');$('#address-results').innerHTML='<p class="small">Recherche dans la base de l’ADEME…</p>';try{$('#address-results').innerHTML=addressResultsHTML(await api('/dpe/address','POST',payload));}catch(error){$('#address-results').innerHTML='';throw error;}}
else if(action==='use-address'){const c=state.addressGroups?.[Number(button.dataset.index)];if(!c)return;const f=$('#edit-form').elements;f.namedItem('address').value=[c.address,c.count===1?c.members[0]?.complement:''].filter(Boolean).join(', ');if(c.postal_code)f.namedItem('postal_code').value=c.postal_code;if(c.city&&!f.namedItem('city').value)f.namedItem('city').value=c.city;toast('Adresse reprise dans la fiche. Enregistrez pour la conserver.');}
else if(action==='export-source'){download('capture_repere.json',await api('/listings/'+editing.id+'/source'));}
else if(action==='delete-listing'){if(!confirm('Supprimer cette annonce et ses captures ? Les scénarios enregistrés seront conservés.'))return;await api('/listings/'+editing.id,'DELETE');closeModal();await refresh();location.hash='annonces';await route();}
}catch(error){toast(error.message);const err=$('#edit-error')||$('#import-error');if(err)err.textContent=error.message;}finally{button.disabled=false;}});

document.addEventListener('submit',async e=>{const form=e.target;if(!['import-form','edit-form','finance-form','profile-form'].includes(form.id))return;e.preventDefault();const button=e.submitter;button.disabled=true;const original=button.textContent;try{
if(form.id==='import-form'){button.textContent='Analyse en cours…';$('#import-error').textContent='';const data=new FormData(form);const isURL=data.get('import_mode')==='url';let capture={url:String(data.get('source_url')||''),text:'',html:''};if(!isURL){const content=String(data.get('content')||'').trim();if(content.startsWith('{')||content.startsWith('[')){try{const parsed=JSON.parse(content);if(parsed.format==='repere.backup.v1')throw new Error('Utilisez Paramètres → Restaurer pour une sauvegarde complète.');if(parsed.capture)capture={...parsed.capture,url:capture.url||parsed.capture.url||''};else if(parsed.text!==undefined||parsed.html!==undefined)capture={...parsed,url:capture.url||parsed.url||''};else capture.json_ld=[JSON.stringify(parsed)];}catch(err){throw new Error('Fichier JSON invalide ou format non pris en charge. '+err.message);}}else if(/<\/?(?:html|body|main|div|article|!doctype|script|meta|p|section)\b/i.test(content)){capture.html=content;}else capture.text=content;}
capture.use_gemini=data.get('use_gemini')==='on';capture.parsers=data.getAll('parsers');const row=await api('/import','POST',{capture,fetch_url:isURL});closeModal();await refresh();setProject(projectOf(row));location.hash='annonces';await route();await openEditor(row.id);toast('Annonce ajoutée. Vérifiez les données reconnues.');}
else if(form.id==='edit-form'){const data=new FormData(form),facts={};for(const key of Object.keys(labels)){let value=data.get(key);value=numericFacts.has(key)?(value===''?null:Number(value)):(value===''?null:value);if(value!==(editing.facts[key]??null))facts[key]=value;}const payload={facts,notes:String(data.get('notes')||''),status:data.get('status'),reviewed:button.value==='yes'?true:editing.reviewed};if(String(data.get('title'))!==editing.title)payload.title=String(data.get('title'));if(editing.id)payload.revision=editing.revision;const saved=await api('/listings'+(editing.id?'/'+editing.id:''),editing.id?'PATCH':'POST',payload);closeModal();await refresh();setProject(projectOf(saved));location.hash='annonces';await route();toast('Fiche enregistrée.');}
else if(form.id==='finance-form'){$('#finance-error').textContent='';const inputs=collectSimulation();button.textContent='Calcul en cours…';const result=await api('/simulate','POST',inputs);showSimulation(result,inputs);}
else if(form.id==='profile-form'){const data=new FormData(form);const payload=Object.fromEntries([...data].map(([k,v])=>[k,v===''?null:Number(v)]));state.profile=await api('/profile','PUT',payload);toast('Budget enregistré.');}
}catch(error){const id={'import-form':'import-error','edit-form':'edit-error','finance-form':'finance-error','profile-form':'profile-error'}[form.id];if($('#'+id))$('#'+id).textContent=error.message;else toast(error.message);}finally{button.disabled=false;button.textContent=original;}});

boot();
